commands:
# Run in 64-bit PowerShell as Administrator

 # 1) Kill Brave updater processes
 $procs = @(
  'BraveUpdate','brave_installer-x64','BraveCrashHandler','BraveCrashHandler64','BraveCrashHandlerArm64',
  'BraveUpdateBroker','BraveUpdateCore','BraveUpdateOnDemand','BraveUpdateSetup',
  'BraveUpdateComRegisterShell64','BraveUpdateComRegisterShellArm64'
 )
 foreach ($p in $procs) {
  Get-Process -Name $p -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
 }

 # 2) Remove services (if present)
 foreach ($svc in 'brave','bravem','BraveElevationService') {
  if (Get-Service $svc -ErrorAction SilentlyContinue) { sc.exe delete $svc  }
 }

 # 3) Delete updater folder
 $upd = 'C:\Program Files (x86)\BraveSoftware\Update'
 if (Test-Path $upd) { Remove-Item $upd -Recurse -Force -ErrorAction SilentlyContinue }

 # 4) Delete scheduled tasks (discover names with GUIDs)
 $csv = (& schtasks /query /fo CSV l) -join "`n"
 if ($csv) {
  $tasks = $csv | ConvertFrom-Csv |
  Where-Object { $_.TaskName -like '\BraveSoftwareUpdateTaskMachine*' }
  foreach ($t in $tasks) { schtasks /delete /f /tn $t.TaskName  }
 }

 # 5) Registry cleanup (only if keys exist)
 $rk = @(
  'HKLM\Software\Microsoft\Active Setup\Installed Components\{AFE6A462-C574-4B8A-AF43-4CC60DF4563B}',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Logon\{56CA197F-543C-40DC-953C-B9C6196C92A5}',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Plain\{0948A341-8E1E-479F-A667-6169E4D5CB2A}',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tasks\{0948A341-8E1E-479F-A667-6169E4D5CB2A}',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tasks\{56CA197F-543C-40DC-953C-B9C6196C92A5}',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tree\BraveSoftwareUpdateTaskMachineCore',
  'HKLM\Software\Microsoft\Windows NT\CurrentVersion\Schedule\TaskCache\Tree\BraveSoftwareUpdateTaskMachineUA'
 )
 foreach ($p in $rk) {
  & reg.exe query "$p" l 
  if ($LASTEXITCODE -eq 0) { & reg.exe delete "$p" /f  }
 }
